with target as(select * from public.works where id=any(array[1017,1018,1019,1039,1109,1200,1205,2067]::bigint[]) or open_library_id=any(array['OL699602W','OL699601W','OL699585W','OL14988837W','OL3793465W','OL2795318W','OL812225W','OL486626W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['opwegnaarheteinde','nadertotu','moederenzoon','caesarion','aandeanderekantvandedeur','titaantjes','terugtotinadamman','deverborgenglimlach']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['opwegnaarheteinde','nadertotu','moederenzoon','caesarion','aandeanderekantvandedeur','titaantjes','terugtotinadamman','deverborgenglimlach']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL55234A','OL184586A','OL6972374A','OL413987A','OL68474A','OL30401A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['gerardkornelisvanhetreve','gerardreve','tommywieringa','tonkedragt','nescio','jhfgronloh','janhendrikfrederikgronloh','simonvestdijk','svestdijk','niccifrench']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL24649201M','OL24629543M','OL24649202M','OL24947035M','OL46907700M','OL22940108M','OL24650500M','OL12804332M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789028205598','9789028205604','9789010047694','9789023465140','9789025833442','9789023656289','9789001547929','9789041407436']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
